// TTL=3600. Resolver A cached 600s ago, Resolver B cached 3000s ago.
const TTL = 3600;
const caches = [
  { name: 'Resolver A', cachedAgoSec: 600 },
  { name: 'Resolver B', cachedAgoSec: 3000 },
];
for (const c of caches) {
  const remaining = TTL - c.cachedAgoSec; // seconds still serving stale
  console.log(`${c.name}: serves stale for ${remaining}s more`);
}
console.log('No single propagation moment — caches expire one by one.');
